package classes.modern_test;

/** Genuine javac control/frame probes; no generated bytecode or timing oracle. */
public final class JavaCoreControl {
  private static final Object FIRST = new Object();
  private static final Object SECOND = new Object();
  private static final StringBuilder ORDER = new StringBuilder();
  private static Object observed;

  static final class Box {
    int integer;
    long wide;
    double decimal;
    Object reference;

    long mixed(int a, long b, double c, Object ref, int tail) {
      check(c == 3.5 && ref == FIRST);
      return b + a + tail;
    }
  }

  private static void check(boolean condition) {
    if (!condition) throw new AssertionError("Core control probe failed");
  }

  private static void emit(String id, String event) {
    System.out.print(id);
    System.out.print('=');
    System.out.println(event);
  }

  static int zeroMask(int x) {
    return (x == 0 ? 1 : 0) | (x != 0 ? 2 : 0) | (x < 0 ? 4 : 0) |
      (x <= 0 ? 8 : 0) | (x > 0 ? 16 : 0) | (x >= 0 ? 32 : 0);
  }

  static int intMask(int a, int b) {
    return (a == b ? 1 : 0) | (a != b ? 2 : 0) | (a < b ? 4 : 0) |
      (a <= b ? 8 : 0) | (a > b ? 16 : 0) | (a >= b ? 32 : 0);
  }

  static int refMask(Object a, Object b) { return (a == b ? 1 : 0) | (a != b ? 2 : 0); }
  static int nullMask(Object value) { return (value == null ? 1 : 0) | (value != null ? 2 : 0); }

  static int longMask(long a, long b) {
    return (a == b ? 1 : 0) | (a != b ? 2 : 0) | (a < b ? 4 : 0) |
      (a <= b ? 8 : 0) | (a > b ? 16 : 0) | (a >= b ? 32 : 0);
  }

  static int floatMask(float a, float b) {
    return (a == b ? 1 : 0) | (a != b ? 2 : 0) | (a < b ? 4 : 0) |
      (a <= b ? 8 : 0) | (a > b ? 16 : 0) | (a >= b ? 32 : 0);
  }

  static int doubleMask(double a, double b) {
    return (a == b ? 1 : 0) | (a != b ? 2 : 0) | (a < b ? 4 : 0) |
      (a <= b ? 8 : 0) | (a > b ? 16 : 0) | (a >= b ? 32 : 0);
  }

  static int dense(int value) {
    switch (value) {
      case -2: return 12;
      case -1: return 13;
      case 0: return 14;
      case 1: return 15;
      default: return 99;
    }
  }

  static int sparse(int value) {
    switch (value) {
      case Integer.MIN_VALUE: return 21;
      case -7: return 22;
      case 0: return 23;
      case 1000000: return 24;
      case Integer.MAX_VALUE: return 25;
      default: return 99;
    }
  }

  private static boolean markBoolean(int digit, boolean value) { ORDER.append(digit); return value; }
  private static int markInt(int digit, int value) { ORDER.append(digit); return value; }
  private static long markLong(int digit, long value) { ORDER.append(digit); return value; }
  private static double markDouble(int digit, double value) { ORDER.append(digit); return value; }
  private static Object markReference(int digit, Object value) { ORDER.append(digit); return value; }
  static boolean shortAnd(boolean a, boolean b) { return markBoolean(1, a) && markBoolean(2, b); }
  static boolean shortOr(boolean a, boolean b) { return markBoolean(1, a) || markBoolean(2, b); }
  static int conditional(boolean takeFirst) { return takeFirst ? markInt(1, 11) : markInt(2, 22); }

  private static long mix(int i, long j, double d, Object ref) {
    check(i == 3 && j == 5L && d == 7.0 && ref == FIRST);
    return i + j + (long) d;
  }

  static long argumentOrder() {
    return mix(markInt(1, 3), markLong(2, 5L), markDouble(3, 7.0), markReference(4, FIRST));
  }

  static int retI(int value) { return value; }
  static long retJ(long value) { return value; }
  static float retF(float value) { return value; }
  static double retD(double value) { return value; }
  static Object retA(Object value) { return value; }
  static void retV() { observed = FIRST; }

  static long mixed(int a, long b, double c, Object ref, int tail) {
    check(c == 3.5 && ref == FIRST);
    return b + a + tail;
  }

  static long recurse(int depth, long carry, double tag) {
    long savedCarry = carry;
    double savedTag = tag;
    if (depth == 0) return carry;
    long child = recurse(depth - 1, carry + 1, tag + 0.5);
    check(carry == savedCarry && tag == savedTag);
    return child + carry;
  }

  static Object outerLocal0() {
    Object saved = FIRST;
    innerLocal0();
    return saved;
  }

  static void innerLocal0() {
    Object saved = SECOND;
    observed = saved;
  }

  static int fieldPost(Box box) { return box.integer++; }
  static int arrayPost(int[] array, int index) { return array[index]++; }
  static Object assignReference(Box box, Object value) { return box.reference = value; }
  static long fieldPostLong(Box box) { return box.wide++; }
  static long arrayPostLong(long[] array, int index) { return array[index]++; }
  static double fieldPostDouble(Box box) { return box.decimal++; }

  private static int discardI(int value) { ORDER.append('I'); return value; }
  private static long discardJ(long value) { ORDER.append('J'); return value; }
  private static double discardD(double value) { ORDER.append('D'); return value; }
  private static Object discardA(Object value) { ORDER.append('A'); return value; }
  static void discard(int i, long j, double d, Object value) {
    discardI(i);
    discardJ(j);
    discardD(d);
    discardA(value);
  }

  static void caseIfZero() {
    check(zeroMask(Integer.MIN_VALUE) == 14 && zeroMask(-1) == 14 && zeroMask(0) == 41 &&
      zeroMask(1) == 50 && zeroMask(Integer.MAX_VALUE) == 50);
    emit("control-if-zero", "14,14,41,50,50");
  }

  static void caseIfInt() {
    check(intMask(Integer.MIN_VALUE, Integer.MAX_VALUE) == 14 &&
      intMask(Integer.MAX_VALUE, Integer.MIN_VALUE) == 50 && intMask(Integer.MIN_VALUE, Integer.MIN_VALUE) == 41 &&
      intMask(-1, 0) == 14 && intMask(0, -1) == 50);
    emit("control-if-int", "14,50,41,14,50");
  }

  static void caseIfReference() {
    check(refMask(FIRST, FIRST) == 1 && refMask(FIRST, SECOND) == 2 &&
      refMask(null, null) == 1 && refMask(FIRST, null) == 2);
    emit("control-if-reference", "1,2,1,2");
  }

  static void caseIfNull() {
    check(nullMask(null) == 1 && nullMask(FIRST) == 2);
    emit("control-if-null", "1,2");
  }

  static void caseLongCompare() {
    check(longMask(Long.MIN_VALUE, Long.MAX_VALUE) == 14 && longMask(Long.MAX_VALUE, Long.MIN_VALUE) == 50 &&
      longMask(4294967296L, 0L) == 50 && longMask(9007199254740993L, 9007199254740992L) == 50 &&
      longMask(Long.MAX_VALUE, Long.MAX_VALUE) == 41);
    emit("control-long-compare", "14,50,50,50,41");
  }

  static void caseFloatCompare() {
    check(floatMask(Float.NEGATIVE_INFINITY, Float.POSITIVE_INFINITY) == 14 && floatMask(Float.NaN, 1) == 2 &&
      floatMask(1, Float.NaN) == 2 && floatMask(-0.0f, 0.0f) == 41 &&
      floatMask(Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY) == 41);
    emit("control-float-compare", "14,2,2,41,41");
  }

  static void caseDoubleCompare() {
    check(doubleMask(Double.NEGATIVE_INFINITY, Double.POSITIVE_INFINITY) == 14 && doubleMask(Double.NaN, 1) == 2 &&
      doubleMask(1, Double.NaN) == 2 && doubleMask(-0.0, 0.0) == 41 &&
      doubleMask(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY) == 41);
    emit("control-double-compare", "14,2,2,41,41");
  }

  static void caseDenseSwitch() {
    check(dense(-3) == 99 && dense(-2) == 12 && dense(-1) == 13 && dense(0) == 14 && dense(1) == 15 && dense(2) == 99);
    emit("control-dense-switch", "99,12,13,14,15,99");
  }

  static void caseSparseSwitch() {
    check(sparse(Integer.MIN_VALUE) == 21 && sparse(-8) == 99 && sparse(-7) == 22 && sparse(0) == 23 &&
      sparse(1) == 99 && sparse(1000000) == 24 && sparse(Integer.MAX_VALUE) == 25);
    emit("control-sparse-switch", "21,99,22,23,99,24,25");
  }

  static void caseShortCircuit() {
    ORDER.setLength(0); check(!shortAnd(false, true) && ORDER.toString().equals("1"));
    ORDER.setLength(0); check(!shortAnd(true, false) && ORDER.toString().equals("12"));
    ORDER.setLength(0); check(shortAnd(true, true) && ORDER.toString().equals("12"));
    ORDER.setLength(0); check(shortOr(true, false) && ORDER.toString().equals("1"));
    ORDER.setLength(0); check(shortOr(false, true) && ORDER.toString().equals("12"));
    ORDER.setLength(0); check(!shortOr(false, false) && ORDER.toString().equals("12"));
    emit("control-short-circuit", "and=F/1,F/12,T/12;or=T/1,T/12,F/12");
  }

  static void caseConditional() {
    ORDER.setLength(0); check(conditional(true) == 11 && ORDER.toString().equals("1"));
    ORDER.setLength(0); check(conditional(false) == 22 && ORDER.toString().equals("2"));
    emit("control-conditional", "11/1,22/2");
  }

  static void caseArgumentOrder() {
    ORDER.setLength(0);
    check(argumentOrder() == 15L && ORDER.toString().equals("1234"));
    emit("control-argument-order", "order=1234;value=15;reference=same");
  }

  static void caseReturns() {
    check(retI(-17) == -17 && retJ(9007199254740993L) == 9007199254740993L &&
      retF(3.5f) == 3.5f && retD(-7.25) == -7.25 && retA(FIRST) == FIRST && retA(null) == null);
    observed = null; retV(); check(observed == FIRST);
    emit("control-returns", "I=-17;J=9007199254740993;F=3.5;D=-7.25;A=same/null;V=done");
  }

  static void caseMixedSlots() {
    int a = 2, tail = 7; long b = 9007199254740993L; double c = 3.5; Object ref = FIRST;
    check(mixed(a, b, c, ref, tail) == 9007199254741002L);
    check(new Box().mixed(a, b, c, ref, tail) == 9007199254741002L);
    check(a == 2 && tail == 7 && b == 9007199254740993L && c == 3.5 && ref == FIRST);
    emit("control-mixed-slots", "static=9007199254741002;instance=9007199254741002;caller=unchanged");
  }

  static void caseRecursion() {
    check(recurse(3, 10L, 0.5) == 46L && recurse(0, 10L, 0.5) == 10L);
    emit("control-recursion", "46,10;locals=preserved");
  }

  static void caseFreshLocals() {
    check(outerLocal0() == FIRST && observed == SECOND);
    check(outerLocal0() == FIRST && observed == SECOND);
    emit("control-fresh-locals", "outer=A;inner=B;repeat=A");
  }

  static void caseWideInt() {
    check(CoreControlWideHelpers.wideInt(1, 0) == 560 && CoreControlWideHelpers.wideInt(1, 1) == -42 &&
      CoreControlWideHelpers.wideInt(1, 2) == 33929 && CoreControlWideHelpers.wideInt(-1, 0) == 558 &&
      CoreControlWideHelpers.wideInt(-1, 1) == -44 && CoreControlWideHelpers.wideInt(-1, 2) == 33409);
    emit("control-wide-int", "560,-42,33929;558,-44,33409");
  }

  static void caseWideReference() {
    check(CoreControlWideHelpers.wideReference(FIRST, 1) == FIRST && CoreControlWideHelpers.wideReference(null, -1) == null);
    emit("control-wide-reference", "same,null");
  }

  static void caseWideFloat() {
    check(CoreControlWideHelpers.wideFloat(3.5f, 1) == 3.5f && CoreControlWideHelpers.wideFloat(-7.25f, -1) == -7.25f);
    emit("control-wide-float", "3.5,-7.25");
  }

  static void caseWideCategory2() {
    check(CoreControlWideHelpers.wideLong(9007199254740993L, 1) == 9007199254740993L &&
      CoreControlWideHelpers.wideDouble(1.25, -1) == 1.25);
    emit("control-wide-category2", "9007199254740993,1.25");
  }

  static void caseWideConstant() {
    check(CoreControlWideHelpers.constant(0).equals("constant000") &&
      CoreControlWideHelpers.constant(127).equals("constant127") &&
      CoreControlWideHelpers.constant(299).equals("constant299") &&
      CoreControlWideHelpers.constant(-1).equals("default"));
    emit("control-wide-constant", "constant000,constant127,constant299,default");
  }

  static void caseWideForward() {
    check(CoreControlWideHelpers.forward(false) == 7 && CoreControlWideHelpers.forward(true) == 12007);
    emit("control-wide-forward", "7,12007");
  }

  static void caseWideBackward() {
    check(CoreControlWideHelpers.backward(0) == 7 && CoreControlWideHelpers.backward(1) == 12007 &&
      CoreControlWideHelpers.backward(2) == 24007);
    emit("control-wide-backward", "7,12007,24007");
  }

  static void caseCompoundCategory1() {
    Box box = new Box(); box.integer = 3; int[] array = {5};
    check(fieldPost(box) == 3 && box.integer == 4 && arrayPost(array, 0) == 5 && array[0] == 6 &&
      assignReference(box, FIRST) == FIRST && box.reference == FIRST);
    emit("control-compound-category1", "field=3/4;array=5/6;reference=same");
  }

  static void caseCompoundCategory2() {
    Box box = new Box(); box.wide = 7L; box.decimal = 1.5; long[] array = {9L};
    check(fieldPostLong(box) == 7L && box.wide == 8L && arrayPostLong(array, 0) == 9L && array[0] == 10L &&
      fieldPostDouble(box) == 1.5 && box.decimal == 2.5);
    emit("control-compound-category2", "field=7/8;array=9/10;double=1.5/2.5");
  }

  static void caseDiscard() {
    ORDER.setLength(0); discard(3, 4L, 5.0, FIRST);
    check(ORDER.toString().equals("IJDA") && retJ(9L) == 9L && retA(FIRST) == FIRST);
    emit("control-discard", "order=IJDA;next-call=normal");
  }

  public static void main(String[] args) {
    caseIfZero(); caseIfInt(); caseIfReference(); caseIfNull();
    caseLongCompare(); caseFloatCompare(); caseDoubleCompare();
    caseDenseSwitch(); caseSparseSwitch(); caseShortCircuit(); caseConditional();
    caseArgumentOrder(); caseReturns(); caseMixedSlots(); caseRecursion(); caseFreshLocals();
    caseWideInt(); caseWideReference(); caseWideFloat(); caseWideCategory2(); caseWideConstant();
    caseWideForward(); caseWideBackward(); caseCompoundCategory1(); caseCompoundCategory2(); caseDiscard();
    System.out.println("CORE_CONTROL_OK");
  }
}
